# Seuil d'avant -> caractéristique qui donne une difficulté comparable en opposition.
THRESHOLD_TO_STAT = {10: 6, 13: 12, 16: 18}


def thresholds_to_stats(apps, schema_editor):
    Monster = apps.get_model('ivakar_rpg', 'Monster')
    for monster in Monster.objects.all():
        monster.dexterite = THRESHOLD_TO_STAT.get(monster.hit_difficulty, 6)
        monster.force = THRESHOLD_TO_STAT.get(monster.dodge_difficulty, 6)
        mind = min(100, 4 + 2 * monster.level)
        monster.perception = monster.intelligence = monster.mental = mind
        monster.save(update_fields=['dexterite', 'force', 'perception', 'intelligence', 'mental'])
    WorldEvent = apps.get_model('ivakar_rpg', 'WorldEvent')
    for event in WorldEvent.objects.all():
        event.dexterite = THRESHOLD_TO_STAT.get(event.hit_difficulty, 12)
        event.save(update_fields=['dexterite'])


